{"name": "write_file", "arguments": {"path": "todo.py", "content": "#!/usr/bin/env python3
import sys
import json

def add_task(task):
    try:
        with open('tasks.json', 'r') as f:
            tasks = json.load(f)
    except FileNotFoundError:
        tasks = []
    tasks.append({'task': task, 'done': False})
    with open('tasks.json', 'w') as f:
        json.dump(tasks, f, indent=4)


def list_tasks():
    try:
        with open('tasks.json', 'r') as f:
            tasks = json.load(f)
    except FileNotFoundError:
        tasks = []
    for i, task in enumerate(tasks):
        status = '[x]' if task['done'] else '[ ]'
        print(f'{i + 1}. {status} {task["task"]}')


def mark_done(index):
    try:
        with open('tasks.json', 'r') as f:
            tasks = json.load(f)
    except FileNotFoundError:
        print('No tasks to mark done.')
        return
    if 0 <= index < len(tasks):
        tasks[index]['done'] = True
        with open('tasks.json', 'w') as f:
            json.dump(tasks, f, indent=4)
    else:
        print('Invalid task index.')


if __name__ == '__main__':
    if len(sys.argv) < 2:
        print('Usage: python3 todo.py <add|list|done> [task]')
        sys.exit(1)
    command = sys.argv[1]
    if command == 'add' and len(sys.argv) > 2:
        add_task(' '.join(sys.argv[2:]))
    elif command == 'list':
        list_tasks()
    elif command == 'done' and len(sys.argv) > 2:
        try:
            index = int(sys.argv[2]) - 1
            mark_done(index)
        except ValueError:
            print('Please provide a valid task number.')"}}
